def icone(nome: str) -> str:
    """O <svg> do ícone; se o nome não for conhecido, o próprio texto (um emoji, por exemplo)."""
    if nome not in FORMAS:
        return escape(nome)
    return (
        '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" '
        f'stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{FORMAS[nome]}</svg>'
    )
